package app.mycelium.app.ui

import android.content.Context
import android.media.AudioAttributes
import android.media.MediaPlayer
import android.media.SoundPool
import android.os.SystemClock
import androidx.compose.runtime.staticCompositionLocalOf

/**
 * The app's sound effects and jar ambience (generated by scripts/gen_sounds.py into assets/sounds/).
 * Effects play through SoundPool; the ambience is one looping MediaPlayer that runs only on the Terrarium while the
 * app is in front. Volumes come from Settings > Sound (master x effects / ambience, mute) and the phone's media volume.
 */
class Sounds(context: Context) {
    private val app = context.applicationContext
    private val attrs = AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_GAME).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build()
    private val pool = SoundPool.Builder().setMaxStreams(8).setAudioAttributes(attrs).build()
    private val ids = HashMap<String, Int>()
    private val last = HashMap<String, Long>()
    private var effects = 0.8f
    private var ambience = 0.5f
    private var ambName: String? = null
    private var player: MediaPlayer? = null
    private var paused = false
    private val ready = HashSet<Int>()
    private val waiting = HashMap<Int, Pair<Float, Float>>()   // asked for before it finished loading: play when ready

    init {
        pool.setOnLoadCompleteListener { p, id, status ->
            if (status != 0) return@setOnLoadCompleteListener
            ready += id
            waiting.remove(id)?.let { (v, rate) -> p.play(id, v, v, 1, 0, rate) }
        }
        for (f in app.assets.list("sounds").orEmpty()) if (f.endsWith(".wav") && !f.startsWith("amb_")) {
            runCatching { app.assets.openFd("sounds/$f").use { ids[f.removeSuffix(".wav")] = pool.load(it, 1) } }
        }
    }

    /** One effect. [rate] shifts the pitch (bigger creatures sound lower); the same sound never stacks within 60 ms. */
    fun play(name: String, rate: Float = 1f, volume: Float = 1f) {
        val id = ids[name] ?: return
        if (effects <= 0f) return
        val now = SystemClock.uptimeMillis()
        if (now - (last[name] ?: 0L) < 60) return
        last[name] = now
        val v = (effects * volume).coerceIn(0f, 1f)
        if (id !in ready) { waiting[id] = v to rate.coerceIn(0.5f, 2f); return }
        pool.play(id, v, v, 1, 0, rate.coerceIn(0.5f, 2f))
    }

    fun setVolumes(muted: Boolean, master: Int, effectsOn: Boolean, effectsLevel: Int, ambienceOn: Boolean, ambienceLevel: Int) {
        val m = if (muted) 0f else master / 100f
        effects = if (effectsOn) m * effectsLevel / 100f else 0f
        ambience = if (ambienceOn) m * ambienceLevel / 100f else 0f
        player?.setVolume(ambience, ambience)
        if (ambience <= 0f) stopAmbience() else ambName?.let { if (player == null && !paused) startAmbience(it) }
    }

    /** The jar's background loop ("amb_day" / "amb_night"), or null to stop it. */
    fun ambience(name: String?) {
        if (name == ambName && (player != null || ambience <= 0f || paused)) return
        stopAmbience()
        ambName = name
        if (name != null && ambience > 0f && !paused) startAmbience(name)
    }

    private fun startAmbience(name: String) {
        player = runCatching {
            MediaPlayer().apply {
                app.assets.openFd("sounds/$name.wav").use { setDataSource(it.fileDescriptor, it.startOffset, it.length) }
                setAudioAttributes(attrs)
                isLooping = true
                setVolume(ambience, ambience)
                prepare()
                start()
            }
        }.getOrNull()
    }

    private fun stopAmbience() {
        player?.runCatching { stop(); release() }
        player = null
    }

    fun onPause() { paused = true; stopAmbience() }
    fun onResume() { paused = false; ambName?.let { if (ambience > 0f) startAmbience(it) } }
    fun release() { stopAmbience(); pool.release() }
}

val LocalSounds = staticCompositionLocalOf<Sounds?> { null }
